<?php namespace App\Filament\Resources\PropertyAcquisitionResource\Pages; use App\Filament\Resources\PropertyAcquisitionResource; use App\Services\PropertyAcquisitionService; use Filament\Actions; use Filament\Resources\Pages\ViewRecord; class ViewPropertyAcquisition extends ViewRecord { protected static string $resource=PropertyAcquisitionResource::class; protected function getHeaderActions():array{return [Actions\Action::make('startDueDiligence')->label('Start due diligence')->visible(fn()=>$this->record->status==='draft')->action(fn()=>app(PropertyAcquisitionService::class)->transition(auth()->user(),$this->record,'under_due_diligence')),Actions\Action::make('approve')->visible(fn()=>$this->record->status==='under_due_diligence')->authorize('approve')->action(fn()=>app(PropertyAcquisitionService::class)->transition(auth()->user(),$this->record,'approved')),Actions\Action::make('complete')->visible(fn()=>$this->record->status==='approved')->authorize('complete')->action(fn()=>app(PropertyAcquisitionService::class)->transition(auth()->user(),$this->record,'completed')),Actions\Action::make('cancel')->requiresConfirmation()->form([\Filament\Forms\Components\Textarea::make('reason')->required()])->authorize('cancel')->action(fn(array $data)=>app(PropertyAcquisitionService::class)->transition(auth()->user(),$this->record,'cancelled',$data['reason']))];} }
